// План specs/addresses.md 3.3–3.4 (кейс AD-08). Admin, компания «test». Только просмотр, JobDetail не открываем (автосохранение).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from './address-helpers';
import {
  QA_UNIT_CLIENT_ID, TEST_CLIENT_ID, expectNoBrokenUnitFormat, expectUnitRightAfterStreet, jobEntryText, openCustomerJobs, pickAddress,
} from './address-display-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: Unit работы во вкладке Jobs клиента (#b2f74544)', () => {
  test('Customer "test" Jobs tab: each job shows its own Unit right after the street #b2f74544 @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await openCustomerJobs(page, TEST_CLIENT_ID, 'JOB-0011');

    for (const [job, unit] of [['JOB-0011', 'Unit 1234'], ['JOB-0009', 'Unit 12213']]) {
      const entry = await jobEntryText(page, job, '2221 NW Federal Hwy');
      // Адрес самой работы (Service Location) с её Unit, а не адрес клиента (Unit 3123).
      expect(entry, job).toContain(`2221 NW Federal Hwy, ${unit}, Stuart, FL 34994, USA`);
      expectUnitRightAfterStreet(pickAddress(entry, '2221 NW Federal Hwy'), `Jobs клиента «test», ${job}`);
    }
    expectNoBrokenUnitFormat(await page.locator('main').innerText(), 'Страница клиента «test», Jobs');
  });

  test('Customer "QA-unit client" Jobs tab: Suite and # are shown as typed, right after the street #b2f74544 @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await openCustomerJobs(page, QA_UNIT_CLIENT_ID, 'JOB-0044');

    const cases = [
      { job: 'JOB-0044', street: '350 5th Ave', expected: /350 5th Ave, Suite 3300, New York, NY 10118, USA/ },
      { job: 'JOB-0047', street: '2221 Northwest Federal Highway', expected: /2221 Northwest Federal Highway, #12, Stuart, Florida/ },
    ];
    for (const c of cases) {
      const entry = await jobEntryText(page, c.job, c.street);
      expect(entry, c.job).toMatch(c.expected);
      expectUnitRightAfterStreet(pickAddress(entry, c.street), `Jobs клиента «QA-unit client», ${c.job}`);
    }
    expectNoBrokenUnitFormat(await page.locator('main').innerText(), 'Страница клиента «QA-unit client», Jobs');
  });
});
